def transform(grid):
    h,w=len(grid),len(grid[0]); bg=max(set(x for row in grid for x in row), key=lambda x:sum(row.count(x) for row in grid))
    out=[row[:] for row in grid]
    # The task's patterned rectangles use colors that differ from the dominant background;
    # each contiguous object's bounding box is a solid rectangle with occasional intrusions.
    from collections import deque
    for color in set(x for row in grid for x in row)-{bg}:
        seen=set()
        for r in range(h):
          for c in range(w):
            if grid[r][c]!=color or (r,c) in seen: continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
              y,x=q.popleft(); cells.append((y,x))
              for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                if 0<=yy<h and 0<=xx<w and grid[yy][xx]==color and (yy,xx) not in seen:
                  seen.add((yy,xx)); q.append((yy,xx))
            r0=min(y for y,x in cells); r1=max(y for y,x in cells); c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            area=(r1-r0+1)*(c1-c0+1)
            # Rectangular colored patches: replace any contaminant cells within their footprint.
            if area>len(cells) and len(cells)/area>=0.65:
              for y in range(r0,r1+1):
                for x in range(c0,c1+1): out[y][x]=color
    return out
